/// <summary>
/// Charge through lines creation class
/// MPJ_37288_ChargebackChargethrough_extension (MPJ_3587)
/// </summary>
public class METCBCTInvoiceLinesCreation
{
}

Method.Source:
/// <summary>
/// Entry point of the class
/// </summary>
/// <param name="args"><c>Args</c></param>
static void main(Args args)
{
    METCBCTInvoiceLinesCreation       ctInvoiceLinesCreation = METCBCTInvoiceLinesCreation::construct();
    FormDataSource              formDataSource;
    METCBCTInvoiceHeaderTable   invoiceHeaderTable;
    Common                      common;
    common = args.record();        
    if (common.TableId  == tableNum(METCBCTInvoiceHeaderTable))           
    {
        invoiceHeaderTable = args.record();
        if (invoiceHeaderTable.Status == METCBCTInvoiceStatus::Processed)
        {
            throw Error("@MET:ChargethroughInvoiceIsAlreadyProcessed");
        }
        if (invoiceHeaderTable.DocumentDate == dateNull())
        {
            throw Error("@MET:DocumentDateMustBeDefined");
        }
        ctInvoiceLinesCreation.createMETCBCTInvoiceLine(args.record());
    }
    else
    {
        throw error(strfmt("@SYS19306","@MET:Posting"));
    }

    if (FormDataUtil::isFormDataSource(args.record()))
    {
        formDataSource = FormDataUtil::getFormDataSource(args.record());
        formDataSource.research(true);
    }
}

/// <summary>
///  Create a new instance of  METCBCTInvoiceCreation class
/// </summary>
/// <returns>
/// A new instance of METCBCTInvoiceCreation class
/// </returns>
public static METCBCTInvoiceLinesCreation construct()
{
    return new METCBCTInvoiceLinesCreation();
}

/// <summary>
///  Create Records in METCBCTInvoiceLine
/// </summary>
/// <param name="_metCBCTInvoiceHeaderTable"><c>METCBCTInvoiceHeaderTable</c></param>
public  void createMETCBCTInvoiceLine(METCBCTInvoiceHeaderTable _metCBCTInvoiceHeaderTable)
{
    
    if(_metCBCTInvoiceHeaderTable.VendInvoiceAmtInclGST)
    {
        METCBCTInvoiceLine   metCBCTInvoiceLine;
        if(this.isLineExists(_metCBCTInvoiceHeaderTable))
        {
            
            boolean confirm = Box::yesNo("@MET:DeleteInvoiceLines",DialogButton::No);
            if(confirm)
            {
                delete_from metCBCTInvoiceLine 
                where metCBCTInvoiceLine.HeaderNumber == _metCBCTInvoiceHeaderTable.Number;
            }
            else
            {
                Info("@MET:NoRecordsDeleted");
            }
        }
        
        Percent gstPercent = this.getGSTPercentage(_metCBCTInvoiceHeaderTable);
        if(_metCBCTInvoiceHeaderTable.VendInvoiceGSTAmount>(_metCBCTInvoiceHeaderTable.VendInvoiceAmtInclGST-_metCBCTInvoiceHeaderTable.VendInvoiceGSTAmount))
        {
            throw Error("@MET:GSTPercentageIsMoreThanNetInvoiceAmount");
        }
        if(gstPercent > 10)
        {
            throw Error("@MET:GSTPercentageIsMoreThan10Pct");
        }
        else
        {
            this.handleInvoiceLineCreation(_metCBCTInvoiceHeaderTable,gstPercent);
        }             
        
    }
    else
    {
        throw Error("@SYS26062"+' '+"@MET:CBCTVendorInvoiceAmountInclGST" + ' '+"@SYS153019");
    }        
    
}

/// <summary>
///  check whether lines exist
/// </summary>
/// <returns>
/// return boolean
/// </returns>
/// <param name="_metCBCTInvoiceHeaderTable"><c>METCBCTInvoiceHeaderTable</c></param>
public  boolean isLineExists(METCBCTInvoiceHeaderTable _metCBCTInvoiceHeaderTable)
{
    boolean lineExist;
    METCBCTInvoiceLine metCBCTInvoiceLine;
    select firstonly RecId from metCBCTInvoiceLine
        where metCBCTInvoiceLine.HeaderNumber == _metCBCTInvoiceHeaderTable.Number;
    if(metCBCTInvoiceLine.RecId)
    {
        lineExist = true;
    }
    return lineExist;
}

/// <summary>
///  check whether vendor allocation exist
/// </summary>
/// <returns>
/// return boolean
/// </returns>
/// <param name="_vendAccount"><c>vendor Account</c></param>
public  boolean isVendAllocExists(VendAccount _vendAccount)
{
    boolean allocExist;
    METCBCTDeptAllocTable metCBCTDeptAllocTable = METCBCTDeptAllocTable::findVendor(_vendAccount);        
    if(metCBCTDeptAllocTable)
    {
        allocExist = true;
    }
    return allocExist;
}

/// <summary>
///  calculate GST percentage
/// </summary>
/// <returns>
/// return real
/// </returns>
/// <param name="_metCBCTInvoiceHeaderTable"><c>METCBCTInvoiceHeaderTable</c></param>
public  Percent getGSTPercentage(METCBCTInvoiceHeaderTable _metCBCTInvoiceHeaderTable)
{
    Percent gstPercent;
    Amount netAmount = _metCBCTInvoiceHeaderTable.VendInvoiceAmtInclGST - _metCBCTInvoiceHeaderTable.VendInvoiceGSTAmount;
    gstPercent = (_metCBCTInvoiceHeaderTable.VendInvoiceGSTAmount/netAmount)*100;
    return gstPercent;
}

/// <summary>
///  calculate GST percentage
/// </summary>
/// <returns>
/// return real
/// </returns>
/// <param name="_metCBCTInvoiceHeaderTable"><c>METCBCTInvoiceHeaderTable</c></param>
public  amount getRemainingBaseAmount(METCBCTInvoiceHeaderTable _metCBCTInvoiceHeaderTable)
{
    Amount  baseAmountForGST    = _metCBCTInvoiceHeaderTable.VendInvoiceGSTAmount*10;
    Amount  remainingBaseAmount = _metCBCTInvoiceHeaderTable.VendInvoiceAmtInclGST-baseAmountForGST-_metCBCTInvoiceHeaderTable.VendInvoiceGSTAmount;
    return remainingBaseAmount;
}

    /// <summary>
    /// Create invoice line
    /// </summary>    
    /// <param name="_metCBCTInvoiceHeaderTable"><c>METCBCTInvoiceHeaderTable</c></param>
    /// <param name="_metCBCTVendCust"><c>METCBCTVendCust</c></param>
    /// <param name="_gstGroup"><c>line creation gst group</c></param>
    /// <param name="_amount"><c>amount</c></param>
    /// <param name="_allocItemId"><c>Item id from allocation</c></param>
    public  void createInvoiceLine(METCBCTInvoiceHeaderTable _metCBCTInvoiceHeaderTable, 
                                   METCBCTVendCust _metCBCTVendCust, Amount _amount, 
                                   TaxItemGroup _gstGroup='', ItemId _allocItemId='')
    {
        METCBCTInvoiceLine  metCBCTInvoiceLine;        
        CustTable           custTable               = CustTable::find(_metCBCTInvoiceHeaderTable.CustomerAccount); 
        VendTable           vendTable               = VendTable::find(_metCBCTInvoiceHeaderTable.VendorAccount);
        metCBCTInvoiceLine.HeaderNumber             = _metCBCTInvoiceHeaderTable.Number;
        metCBCTInvoiceLine.VendCustType             = _metCBCTVendCust;
        if(_allocItemId)
        {
            metCBCTInvoiceLine.ItemId               = _allocItemId;
        }
        else
        {
            metCBCTInvoiceLine.ItemId               = METVendTable::find(vendTable.AccountNum).CBCTServiceItemId;
        }              
        metCBCTInvoiceLine.Qty                      = 1;
        metCBCTInvoiceLine.Amount                   = _amount;
        metCBCTInvoiceLine.TaxItemGroup             = _gstGroup;
        metCBCTInvoiceLine.TaxGroup                 = _gstGroup;
        switch(metCBCTInvoiceLine.VendCustType)
        {
            case METCBCTVendCust::Vend:                
                metCBCTInvoiceLine.InventSiteId     = vendTable.InventSiteId;
                metCBCTInvoiceLine.InventLocationId = vendTable.InventLocation;
                break;
            case METCBCTVendCust::Cust:                
                metCBCTInvoiceLine.InventSiteId     = custTable.InventSiteId;
                metCBCTInvoiceLine.InventLocationId = custTable.InventLocation;
                break;
        }        
        
        metCBCTInvoiceLine.FinancialDimension   = METCBCTInvoiceLine::initFinancialDimension(metCBCTInvoiceLine.ItemId,_metCBCTInvoiceHeaderTable.FinancialDimension);
        metCBCTInvoiceLine.insert();

    }

    /// <summary>
    /// Create invoice line
    /// </summary>    
    /// <param name="_metCBCTInvoiceHeaderTable"><c>METCBCTInvoiceHeaderTable</c></param>    
    /// <param name="_gstPercent"><c>GSTPercent</c></param>
    public  void handleInvoiceLineCreation(METCBCTInvoiceHeaderTable _metCBCTInvoiceHeaderTable,
                                   Percent _gstPercent )
    {
        boolean allocation; 
        METCBCTParameters   metCBCTParameters = METCBCTParameters::Find();
        
        //check whether the allocation exist
        if(METCBCTDeptAllocTable::findVendor(_metCBCTInvoiceHeaderTable.VendorAccount))
        {
            if(METCBCTDeptAllocTable::getTotalAllocPctperVendor(_metCBCTInvoiceHeaderTable.VendorAccount) != 100)
            {
                throw error("@MET:AllocationPercentageNotFullyDefinedToMatch100Pct");
            }
            else
            {
                allocation = true;
            }
        }
        //if GST percent is 10 % of the base amount create lines for vendor and customer. Split lines if allocation exist
        if(_gstPercent == 10)
        {
            Amount  baseAmount = _metCBCTInvoiceHeaderTable.VendInvoiceAmtInclGST-_metCBCTInvoiceHeaderTable.VendInvoiceGSTAmount;
            if(allocation)
            {
                
                METCBCTDeptAllocTable   metCBCTDeptAllocTable;
                while select metCBCTDeptAllocTable
                    where metCBCTDeptAllocTable.VendAccount == _metCBCTInvoiceHeaderTable.VendorAccount
                {
                    Amount allocatedAmount = baseAmount* (metCBCTDeptAllocTable.AllocationPct/100);
                    this.createInvoiceLine(_metCBCTInvoiceHeaderTable, METCBCTVendCust::Cust,allocatedAmount,metCBCTParameters.CreateLineItemGSTGroupTenPct,metCBCTDeptAllocTable.ServiceItemId);
                    this.createInvoiceLine(_metCBCTInvoiceHeaderTable, METCBCTVendCust::Vend,allocatedAmount,metCBCTParameters.CreateLineItemGSTGroupTenPct,metCBCTDeptAllocTable.ServiceItemId);
                   
                }
            }
            else
            {
                this.createInvoiceLine(_metCBCTInvoiceHeaderTable, METCBCTVendCust::Vend,baseAmount,metCBCTParameters.CreateLineItemGSTGroupTenPct);
                this.createInvoiceLine(_metCBCTInvoiceHeaderTable, METCBCTVendCust::Cust,baseAmount,metCBCTParameters.CreateLineItemGSTGroupTenPct);
            }
        }
        else if(_gstPercent < 10) //The amount is more than the GST amount
        {
            Amount baseGstAmount        = _metCBCTInvoiceHeaderTable.VendInvoiceGSTAmount*10;
            Amount remainingBaseAmount  = this.getRemainingBaseAmount(_metCBCTInvoiceHeaderTable);
            if(allocation)
            {               
                
                METCBCTDeptAllocTable   metCBCTDeptAllocTable;
                while select metCBCTDeptAllocTable
                    where metCBCTDeptAllocTable.VendAccount == _metCBCTInvoiceHeaderTable.VendorAccount
                {
                    Amount allocatedBaseAmount      = baseGstAmount* (metCBCTDeptAllocTable.AllocationPct/100);
                    Amount allocatedRemainAmount    = remainingBaseAmount* (metCBCTDeptAllocTable.AllocationPct/100);  

                    this.createInvoiceLine(_metCBCTInvoiceHeaderTable, METCBCTVendCust::Cust,allocatedBaseAmount,metCBCTParameters.CreateLineItemGSTGroupTenPct);
                    this.createInvoiceLine(_metCBCTInvoiceHeaderTable, METCBCTVendCust::Vend,allocatedBaseAmount,metCBCTParameters.CreateLineItemGSTGroupTenPct);
                    this.createInvoiceLine(_metCBCTInvoiceHeaderTable, METCBCTVendCust::Cust,allocatedRemainAmount,metCBCTParameters.CreateLineItemGSTGroupZeroPct, metCBCTDeptAllocTable.ServiceItemId);
                    this.createInvoiceLine(_metCBCTInvoiceHeaderTable, METCBCTVendCust::Vend,allocatedRemainAmount,metCBCTParameters.CreateLineItemGSTGroupZeroPct, metCBCTDeptAllocTable.ServiceItemId);
                }
            }
            else
            {
                
                this.createInvoiceLine(_metCBCTInvoiceHeaderTable, METCBCTVendCust::Cust,baseGstAmount,metCBCTParameters.CreateLineItemGSTGroupTenPct);
                this.createInvoiceLine(_metCBCTInvoiceHeaderTable, METCBCTVendCust::Cust,remainingBaseAmount,metCBCTParameters.CreateLineItemGSTGroupZeroPct);
                this.createInvoiceLine(_metCBCTInvoiceHeaderTable, METCBCTVendCust::Vend,baseGstAmount,metCBCTParameters.CreateLineItemGSTGroupTenPct);
                this.createInvoiceLine(_metCBCTInvoiceHeaderTable, METCBCTVendCust::Vend,remainingBaseAmount,metCBCTParameters.CreateLineItemGSTGroupZeroPct);
            }
        }

    }
